files.content:
* { box-sizing: border-box; }
:root {
  color-scheme: light;
  --cream: #f6edda;
  --paper: #fffaf0;
  --ink: #263c35;
  --green: #537b61;
  --orange: #d8784c;
  --line: #dfd2b8;
}
body {
  min-height: 100vh;
  margin: 0;
  padding: 28px 16px;
  display: grid;
  place-items: center;
  background-color: var(--cream);
  background-image: radial-gradient(#d9c9a8 1.5px, transparent 1.5px);
  background-size: 22px 22px;
  color: var(--ink);
  font: 16px/1.5 system-ui, sans-serif;
}
.card {
  width: min(100%, 480px);
  padding: clamp(24px, 6vw, 40px);
  border: 3px solid var(--ink);
  border-radius: 10px;
  background: var(--paper);
  box-shadow: 8px 8px 0 var(--ink);
}
.header { text-align: center; }
.pixel-icon {
  width: 58px;
  height: 58px;
  margin: 0 auto 14px;
  display: grid;
  place-items: center;
  border: 3px solid var(--ink);
  border-radius: 8px;
  background: var(--cream);
  font-size: 30px;
}
.eyebrow { margin: 0; color: var(--green); font-size: 13px; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 4px 0 0; font-size: clamp(30px, 8vw, 40px); line-height: 1.15; }
.subtitle { margin: 8px 0 28px; color: #52625a; }
.field-row { display: grid; grid-template-columns: 1fr 1.15fr; gap: 14px; }
.field { min-width: 0; }
label { display: block; margin-bottom: 7px; font-weight: 750; }
input, select {
  width: 100%;
  min-height: 50px;
  padding: 10px 12px;
  border: 2px solid var(--line);
  border-radius: 6px;
  background: white;
  color: var(--ink);
  font: inherit;
}
input:focus-visible, select:focus-visible, button:focus-visible { outline: 3px solid var(--orange); outline-offset: 3px; }
button {
  width: 100%;
  min-height: 52px;
  margin-top: 18px;
  padding: 12px 16px;
  border: 2px solid var(--ink);
  border-radius: 6px;
  background: var(--green);
  color: white;
  cursor: pointer;
  font: inherit;
  font-weight: 800;
  transition: transform .12s, background-color .12s, box-shadow .12s;
  box-shadow: 0 4px 0 var(--ink);
}
button:hover { background: #42674f; }
button:active { transform: translateY(3px); box-shadow: 0 1px 0 var(--ink); }
.results { margin-top: 30px; }
.section-heading { display: flex; align-items: center; gap: 10px; border-bottom: 2px solid var(--line); padding-bottom: 9px; }
h2 { margin: 0; font-size: 19px; }
.pixel-dot { width: 10px; height: 10px; background: var(--orange); box-shadow: 5px 0 var(--orange), 0 5px var(--orange), 5px 5px var(--orange); }
.message { margin: 14px 0 8px; color: #58645e; }
.result-list { display: grid; gap: 8px; margin: 14px 0 0; padding: 0; list-style: none; }
.result-list:empty { display: none; }
.result-list li { display: flex; justify-content: space-between; gap: 16px; padding: 10px 12px; border: 1px solid var(--line); border-radius: 5px; background: #fffdf7; }
.result-list strong { color: var(--green); font-variant-numeric: tabular-nums; }
footer { margin-top: 24px; padding-top: 14px; border-top: 1px dashed var(--line); color: #65736b; text-align: center; font-size: 14px; }
@media (max-width: 380px) {
  .field-row { grid-template-columns: 1fr; gap: 12px; }
  .card { box-shadow: 5px 5px 0 var(--ink); }
}

const factors = {
  cups: 240,
  tablespoons: 15,
  teaspoons: 5,
  millilitres: 1
};

const labels = {
  cups: 'Cups',
  tablespoons: 'Tablespoons',
  teaspoons: 'Teaspoons',
  millilitres: 'Millilitres'
};

const form = document.querySelector('#converter-form');
const amountInput = document.querySelector('#amount');
const unitInput = document.querySelector('#unit');
const message = document.querySelector('#message');
const resultsList = document.querySelector('#results-list');

function convert() {
  const amount = Number(amountInput.value);
  const source = unitInput.value;
  resultsList.replaceChildren();

  if (amountInput.value.trim() === '' || !Number.isFinite(amount) || amount < 0) {
    message.textContent = 'Please enter a valid amount of 0 or more.';
    return;
  }

  const millilitres = amount * factors[source];
  message.textContent = `${amount.toLocaleString()} ${labels[source].toLowerCase()} is:`;

  for (const unit of Object.keys(factors)) {
    if (unit === source) continue;
    const value = millilitres / factors[unit];
    const item = document.createElement('li');
    const name = document.createElement('span');
    const result = document.createElement('strong');
    name.textContent = labels[unit];
    result.textContent = `${value.toFixed(1)} ${unit === 'millilitres' ? 'ml' : unit === 'cups' ? 'cups' : unit === 'tablespoons' ? 'tbsp' : 'tsp'}`;
    item.append(name, result);
    resultsList.append(item);
  }
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  convert();
});
amountInput.addEventListener('input', convert);
unitInput.addEventListener('change', convert);
convert();
